/* @lc app=leetcode id=2267 lang=kotlin */
class Solution { fun hasValidPath(grid: Array<CharArray>): Boolean = if ((grid.size + grid[0].size - 1) % 2 != 0) false else Array(grid.size) { Array(grid[0].size) { java.util.BitSet(201) } }.apply { if (grid[0][0] == '(') this[0][0].set(1) }.also { dp -> grid.indices.forEach { r -> grid[0].indices.forEach { c -> (0..200).filter { dp[r][c].get(it) }.forEach { b -> listOf(r + 1 to c, r to c + 1).filter { it.first < grid.size && it.second < grid[0].size }.forEach { (nr, nc) -> (b + if (grid[nr][nc] == '(') 1 else -1).takeIf { it in 0..200 }?.let { dp[nr][nc].set(it) } } } } } }.let { it[grid.size - 1][grid[0].size - 1].get(0) } }